<style lang="scss" scoped src="./d-color-select.scss"></style>

<script>
import { Component, Model, Prop, Vue } from "vue-property-decorator";
import DColorPicker from "../d-color-picker/d-color-picker";
import DColorRadio from "./d-color-radio/d-color-radio";

@Component({
  components: {
    DColorPicker,
    DColorRadio,
  },
})
export default class DColorSelect extends Vue {
  @Model("change", { type: String })
  value;

  @Prop({
    type: String,
    required: true,
  })
  label;

  @Prop({
    type: Array,
    default: () => [],
  })
  colors;

  handlePick({ hex }, close) {
    // if the colors doesn't include the selected color, add it
    if (!this.colors.includes(hex)) {
      this.$emit("addColor", [...this.colors, hex]);

      // close color picker method - provided by the DColorPicker component
      close?.();

      // put focus on the newly added color radio
      requestAnimationFrame(() => {
        const allColorRadios = this.$el.querySelectorAll(".DColorRadio__radio");
        const lastRadio = allColorRadios.item(allColorRadios.length - 1);
        lastRadio?.focus();
      });
    }

    this.theValue = hex;
  }

  get theValue() {
    return this.value;
  }

  set theValue(theValue) {
    this.$emit("change", theValue);
  }
}
</script>

<template>
  <div class="DColorSelect" role="radiogroup" :aria-label="label">
    <DColorRadio
      v-for="color in colors"
      v-model="theValue"
      :key="color"
      :label="color"
      :value="color"
    />
    <DColorPicker @pick="handlePick" />
  </div>
</template>
